function wvVisualMarkup(w,{hint=false}={}){
 const cue=wvCue(w);if(!cue||state.settings.visualMemory===false)return '';
 return `<figure class="wv-memory ${hint?'is-hint':''}" data-word-visual="${w.id}"><svg viewBox="0 0 320 180" role="img" aria-label="${esc(cwText(w)+' · '+w.en+'. '+cue.note)}"><rect class="wv-paper" width="320" height="180" rx="24"/><g stroke="var(--wv-color)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" fill="none" aria-hidden="true">${wvScene(cue.scene)}</g></svg><figcaption>${esc(cue.note)}</figcaption></figure>`;
}
function cwVisualHint(id,turn){const q=cwCurrent();if(currentView!=='commonPractice'||!q||q.step.kind!=='recall'||q.s.revealed||q.w.id!==id||q.s.turn!==turn||state.settings.visualMemory===false)return;cwExpose([id]);q.s.usedHint=true;save();studyModal(`<section class="wv-hint"><span class="eyebrow">Visual hint · supported recall</span><h2 lang="zh">${esc(cwText(q.w))}</h2>${wvVisualMarkup(q.w,{hint:true})}<p>${esc(q.w.en)}</p><p class="small muted">Use the picture, then try the plain word. This answer will count as supported practice.</p><button type="button" class="btn primary full" onclick="closeModal();cwRenderPractice()">Try the word ${icon('arrow')}</button></section>`)}

function wvCourseWordMarkup(value){
 if(!value||typeof value!=='string')return '';
 // Usage already displays this example word, even with pictures disabled.
 // Preserve help for a common-word recall paused on another page.
 cwExposeText(value);
 if(state.settings.visualMemory===false)return '';
 const word=value.trim(),matches=CW_WORDS.filter(w=>w.s===word||w.t===word);
 if(matches.length===1)return `<details class="clean-study-section wv-course-word"><summary>${icon('picture')} Picture this word</summary>${wvVisualMarkup(matches[0])}</details>`;
 const chars=[...word];if(chars.length<2||chars.length>8||!chars.every(ch=>/[\u3400-\u9fff]/.test(ch)))return '';
 const shown=[...text(word)];
 return `<details class="clean-study-section wv-course-word"><summary>${icon('picture')} See the word’s shapes</summary><div class="wv-word-parts">${chars.map((ch,i)=>`<button type="button" onclick="showCharacter('${ch}')"><span lang="zh">${esc(shown[i]||ch)}</span><small>${esc((courseCard(ch)||extra[ch])?.meaning?.split(/[;,]/)[0]||'Look up')}</small></button>`).join('<span class="wv-parts-plus" aria-hidden="true">+</span>')}</div><p class="small muted">Notice the order and shape of each character. A word’s meaning may differ from its characters’ separate meanings; use the example sentence above.</p></details>`;
}
